export interface Spatial {
  /**
   * [west, south, east, north] in WGS84 degrees, or a list of such boxes for disjoint areas (no union box).
   */
  bbox?: BboxCoords | [BboxCoords, ...BboxCoords[]];
  crs?: Crs;
  resolution?: Resolution1;
}
/**
 * Spatial detail of the data as a whole: a grid size ({value, unit}) or the unit of aggregation in words ({text}, e.g. district level). Raster pixel size can also go in data[].raster.resolution.
 */
export interface Resolution1 {
  value?: number;
  unit?: "m" | "km" | "degree" | "arcsec" | "arcmin";
  text?: Text;
}
export interface Related {
  /**
   * How a related resource relates to this one (DataCite relation types, subset).
   */
  relation:
    | "IsSupplementTo"
    | "IsDocumentedBy"
    | "IsSupplementedBy"
    | "IsDerivedFrom"
    | "IsSourceOf"
    | "IsPartOf"
    | "HasPart"
    | "IsNewVersionOf"
    | "IsPreviousVersionOf"
    | "IsCitedBy"
    | "References"
    | "IsVariantFormOf";
  scheme: "doi" | "handle" | "url" | "ark" | "mosaic" | "other";
  value: Text;
  title?: Text;
}
/**
 * MOSAIC profile fields. Optional today; required when the mosaic profile is enforced.
 */
export interface MosaicBlock {
  /**
   * @minItems 1
   */
  landscapes?: [
    (
      | "COL-CUM"
      | "PER-PCL"
      | "SEN-FK"
      | "CIV-NZ"
      | "TUN-NW"
      | "ETH-OG"
      | "KEN-LVB"
      | "KEN-LEI"
      | "ZWE-MB"
      | "IND-CH"
      | "MEK-3S"
    ),
    ...(
      | "COL-CUM"
      | "PER-PCL"
      | "SEN-FK"
      | "CIV-NZ"
      | "TUN-NW"
      | "ETH-OG"
      | "KEN-LVB"
      | "KEN-LEI"
      | "ZWE-MB"
      | "IND-CH"
      | "MEK-3S"
    )[]
  ];
  intake?: {
    status?: "draft" | "in-review" | "published" | "withdrawn";
    submitted_by?: Text;
    submitted_on?: IsoDate;
  };
}

/** A record in the MOSAIC metadata standard (ResourceDetail.record). */
export type MosaicRecord = MOSAICMetadataRecordStructure
